            w.insert('end', f"  {'─'*20} {'─'*6} {'─'*8} {'─'*12} {'─'*14}\n", 'dimtext')
            for nb, si in sorted(BASE_SYSTEMS.items()):
                codon_space = nb ** CODON_LEN
