strong_lambda = 1.414e-15  # Yukawa range = hbar*c / m_pi*c^2 = 197.3 MeV*fm / 139.6 MeV = 1.414 fm
strong_g2 = 4 * math.pi * 14 * (hbar * c)  # Tuned for nuclear binding; alpha_s ~14 in effective models
# For QCD-like confinement (Cornell potential parameters, in natural units, converted approximately to SI)
alpha_s = 0.3  # Effective strong coupling for quarkonia
string_tension = 0.18e9 * 1.602e-19 / 1e-15  # 0.18 GeV/fm converted to J/m (approximate)

