_cs6 = max(1, (_n_sec + 7 - 1) // 7)  # info still split across 7 cols
_f1_col_texts = []
for _ci in range(7):
    _f1_col_texts.append('\n\n'.join(_info_sections[_ci * _cs6:(_ci + 1) * _cs6]))
