        Label(_sa_title, x=_sa_x + 8, y=_sa_ty, font_size=9, color=_sa_tcol).draw()
        _sa_ty -= 15
        Label(f"Assemblies: {_sa.total_assemblies}  Codes: {_sa.total_codes}",
              x=_sa_x + 8, y=_sa_ty, font_size=8, color=_TH_TEXT).draw()
        _sa_ty -= 14
        if _sa_has_discovery:
            Label(f"{_sa.run_odds_last_event}",
                  x=_sa_x + 8, y=_sa_ty, font_size=8, color=(60, 255, 120, 255)).draw()
            _sa_ty -= 14
            Label(f"Atoms: {len(_sa._ro_found_life_atoms)}  T={_sa._ro_discovery_time:.1f}s",
                  x=_sa_x + 8, y=_sa_ty, font_size=7, color=_TH_TEXT).draw()
            _sa_ty -= 14
            Label("Press 7 to revert to pre-search state",
                  x=_sa_x + 8, y=_sa_ty, font_size=7, color=(255, 220, 100, 255)).draw()
            _sa_ty -= 14
        if _sa.run_odds_active:
            Label(f"Iter: {_sa.run_odds_iterations:,}/{_sa.run_odds_max_iter:,}",
                  x=_sa_x + 8, y=_sa_ty, font_size=8, color=_TH_TEXT_DIM).draw()
            _sa_ty -= 14
            Label(f"Last: {_sa.run_odds_last_event}",
                  x=_sa_x + 8, y=_sa_ty, font_size=7, color=_TH_TEXT_DIM).draw()
            _sa_ty -= 14
        for _si, _ss in enumerate(_sa.structures[:4]):
            _scol = (180, 255, 200, 255) if _ss.is_alive else (160, 180, 200, 255)
            Label(f"\u25a0 {_ss.name} S:{_ss.stability:.2f}",
                  x=_sa_x + 8, y=_sa_ty, font_size=7, color=_scol).draw()
            _sa_ty -= 13
        for _ci2, _cc in enumerate(_sa.info_codes[:4]):
            _cinfo = InformationCode.CODE_TYPES.get(_cc.code_type, {})
