                (0.40, 'Mouse-level',     (200, 180, 40)),
                (0.55, 'Dog-level',       (160, 200, 60)),
                (0.70, 'Primate-level',   (80, 200, 120)),
                (0.85, 'Child-level',     (60, 180, 220)),
