                _train_norm = min(1.0, _ob.training_step / 500.0)
                _iq_raw = (0.15 * _sr + 0.20 * _gp_avg + 0.15 * _kn_score +
                           0.15 * _graph_score + 0.15 * _phi_norm +
                           0.10 * _fe_norm + 0.10 * _train_norm)
                _iq_raw = max(0.0, min(1.0, _iq_raw))
